def solve(n):
    vals=set(range(n))
    target=set(range(1,n))
    # backtrack, maybe choose start 0
    for start in range(n):
        seq=[start]; used={start}; usedd=set()
        # heuristic: choose next diff descending? at each choose unused difference maybe largest
        def bt():
            if len(seq)==n:
                return len(usedd)==n-1
            cur=seq[-1]
            # Try unused diffs high to low, sign options
            for d in sorted(target-usedd, reverse=True):
                # possible next cur +/- d
                candidates=[]
                for nxt in (cur+d, cur-d):
                    if 0 <= nxt < n and nxt not in used:
                        candidates.append(nxt)
                # maybe order by constraints
                for nxt in candidates:
                    seq.append(nxt); used.add(nxt); usedd.add(d)
                    if bt():
                        return True
                    usedd.remove(d); used.remove(nxt); seq.pop()
            return False
        if bt():
            return seq
